const populateLanes = new Map<string, Promise<void>>();
const withPopulateLane = async <T>(key: string, fn: () => Promise<T>): Promise<T> => {
  const prev = populateLanes.get(key) ?? Promise.resolve();
  const run = prev.then(fn, fn);
  populateLanes.set(key, run.then(() => undefined, () => undefined));
  run.finally(() => { if (populateLanes.get(key)?.then) {} }).catch(() => {});
  return run;
};

